:root {
  --background: #fff;
  --foreground: #18181b;
  --muted: #f1f1f2;
  --muted-foreground: #71717a;
  --border: #e4e4e7;
  --ring: #167e9b;
  color-scheme: light;
  font-family: Inter,-apple-system,BlinkMacSystemFont,"Apple SD Gothic Neo",sans-serif;
}
:root.dark {
  --background: #191919;
  --foreground: #fafafa;
  --muted: #27272a;
  --muted-foreground: #a1a1aa;
  --border: #3f3f46;
  --ring: #66b9d3;
  color-scheme: dark;
}
html,body,#root {
  margin: 0;
  min-height: 100%;
  width: 100%;
  background: var(--background);
  color: var(--foreground);
}
body {
  overflow: auto;
  scrollbar-width: thin;
  -webkit-font-smoothing: antialiased;
}
#root {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px;
  box-sizing: border-box;
}
.demo-container {
  width: 100%;
  max-width: 540px;
  min-width: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 20px;
}
.demo-toolbar {
  display: flex;
  gap: 6px;
  flex-wrap: wrap;
  justify-content: center;
  font-size: 12px;
}
.demo-toolbar button {
  background: var(--muted);
  border: 1px solid var(--border);
  padding: 7px 10px;
  border-radius: 8px;
}
.demo-toolbar button[aria-pressed=true] {
  background: var(--foreground);
  color: var(--background);
}
.demo-status {
  font-size: 12px;
  color: var(--muted-foreground);
  min-height: 18px;
  text-align: center;
}
button {
  cursor: pointer;
}
button:focus-visible,[tabindex]:focus-visible,input:focus-visible {
  outline: 2px solid var(--ring);
  outline-offset: 3px;
}
input,textarea {
  font-size: max(16px,1em);
}
.focus-ring:focus-visible {
  outline: 2px solid var(--ring);
  outline-offset: 3px;
}
html[data-reduced=true] *,html[data-reduced=true] *::before,html[data-reduced=true] *::after {
  animation-duration: .01ms !important;
  animation-iteration-count: 1 !important;
  transition-duration: .01ms !important;
  scroll-behavior: auto !important;
}
@media (max-width:400px) {
  #root {
    padding: 14px;
  }
  .demo-container {
    max-width: 100%;
  }
}
